@RestController
@RequestMapping("/api/documents")
public class DocumentController {

    @GetMapping("/{id}")
    public ResponseEntity<Document> getDocument(@PathVariable Long id, WebRequest request) {
        Document doc = documentService.findById(id);

        // Compute strong ETag based on document version or content hash
        String eTag = "\"" + doc.getVersionHash() + "\"";
        long lastModified = doc.getUpdatedAt().toInstant().toEpochMilli();

        // Check if-none-match and if-modified-since headers via Spring's built-in check
        if (request.checkNotModified(eTag, lastModified)) {
            return null; // Spring automatically sets 304 Not Modified status and clears body
        }

        return ResponseEntity.ok()
                .cacheControl(CacheControl.maxAge(Duration.ofHours(1)).public())
                .eTag(eTag)
                .lastModified(lastModified)
                .body(doc);
    }
}
